#include "stdafx.h"#include "ROC.h"KROC::KROC(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Filter Time (minutes)",  "Hysteresis",  "Direction High",  "High rate of change range",  "Direction Low",  "Low rate of change range"};BOOL KROC::OnParsingSingleText( std::string &szText, RECTL *rc ){  if( m_CurParameterID!=-1 )  {    AddParam( s_MyParameters[m_CurParameterID], szText.c_str() );    CStringA s;    if( !m_CurParameterID )      s.Format( "FilterTime = %s", szText.c_str() );    else if( 1==m_CurParameterID )      s.Format( "Hysteresis = %s", szText.c_str() );    else if( 3==m_CurParameterID )      s.Format( "HighRateOfChangeRange = %s", szText.c_str() );    else if( 5==m_CurParameterID )      s.Format( "LowRateOfChangeRange = %s", szText.c_str() );    if( !s.IsEmpty() )      m_settings.push_back( s.GetBuffer() );    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;//сделать преобразование параметра к виду, пригодному для формирования исполняемого кода  }  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      return TRUE;    }  }  return FALSE;}